#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=versions.env
source "$SCRIPT_DIR/versions.env"

mkdir -p "$BUILD_DIR/downloads" "$SOURCE_DIR"
fetch() {
    local url=$1 output=$2 checksum=$3 algorithm=$4
    if [[ ! -f "$output" ]]; then
        curl --fail --location --retry 3 --output "$output" "$url"
    fi
    printf '%s  %s\n' "$checksum" "$output" | "$algorithm" -c -
}

fetch "$NDK_URL" "$BUILD_DIR/downloads/android-ndk-${NDK_VERSION}-linux.zip" "$NDK_SHA1" sha1sum

if [[ ! -d "$BUILD_DIR/ndk" ]]; then
    unzip -q "$BUILD_DIR/downloads/android-ndk-${NDK_VERSION}-linux.zip" -d "$BUILD_DIR"
    mv "$BUILD_DIR/android-ndk-${NDK_VERSION}" "$BUILD_DIR/ndk"
fi

clone_tag() {
    local url=$1 tag=$2 commit=$3 destination=$4
    if [[ ! -d "$destination/.git" ]]; then
        git clone --depth 1 --branch "$tag" "$url" "$destination"
    fi
    [[ "$(git -C "$destination" rev-parse HEAD)" == "$commit" ]] || {
        printf 'Unexpected commit in %s; remove it and rerun 01-fetch.sh.\n' "$destination" >&2
        exit 1
    }
}
clone_tag "$JELLYFIN_FFMPEG_URL" "$JELLYFIN_FFMPEG_VERSION" "$JELLYFIN_FFMPEG_COMMIT" "$SOURCE_DIR/jellyfin-ffmpeg"
clone_tag "$LIBARIBCAPTION_URL" "$LIBARIBCAPTION_VERSION" "$LIBARIBCAPTION_COMMIT" "$SOURCE_DIR/libaribcaption"
clone_tag "$FREETYPE_URL" "$FREETYPE_TAG" "$FREETYPE_COMMIT" "$SOURCE_DIR/freetype-${FREETYPE_VERSION}"

# The git tree's top-level configure is only a wrapper; the real script is
# builds/unix/configure, generated by autogen.sh (needs autoconf/libtool).
if [[ ! -f "$SOURCE_DIR/freetype-${FREETYPE_VERSION}/builds/unix/configure" ]]; then
    (cd "$SOURCE_DIR/freetype-${FREETYPE_VERSION}" && bash autogen.sh)
fi

ffmpeg="$SOURCE_DIR/jellyfin-ffmpeg"
if [[ ! -f "$ffmpeg/.aribplayer-patches-applied" ]]; then
    # Match builder-ffmpeg's patch stack: push Jellyfin's quilt series first,
    # then apply the local source patch on top.  Quilting creates .pc/ as its
    # durable idempotency record; the explicit stamp also covers our git patch.
    (cd "$ffmpeg" && QUILT_PATCHES=debian/patches quilt push -a)
    ivtc_patch="$THIRD_PARTY_DIR/ffmpeg/patches/0003-add-ivtc-opencl-filter.patch"
    if git -C "$ffmpeg" apply --check "$ivtc_patch"; then
        git -C "$ffmpeg" apply "$ivtc_patch"
    elif ! git -C "$ffmpeg" apply -R --check "$ivtc_patch"; then
        printf 'IVTC patch is neither applicable nor already applied.\n' >&2
        exit 1
    fi
    for patch in \
        "$THIRD_PARTY_DIR/ffmpeg/patches/0004-libaribcaption-bitmap-clear-events.patch" \
        "$THIRD_PARTY_DIR/ffmpeg/patches/0005-mpegts-arib-superimpose-classification.patch" \
        "$THIRD_PARTY_DIR/ffmpeg/patches/0006-libaribcaption-caption-type-option.patch" \
        "$THIRD_PARTY_DIR/ffmpeg/patches/0007-eager-opencl-deinterlace-init.patch"; do
        if git -C "$ffmpeg" apply --check "$patch"; then
            git -C "$ffmpeg" apply "$patch"
        elif ! git -C "$ffmpeg" apply -R --check "$patch"; then
            printf 'FFmpeg patch %s is neither applicable nor already applied.\n' \
                   "$(basename "$patch")" >&2
            exit 1
        fi
    done
    : > "$ffmpeg/.aribplayer-patches-applied"
fi

aribcaption="$SOURCE_DIR/libaribcaption"
if [[ ! -f "$aribcaption/.aribplayer-patch-applied" ]]; then
    font_patch="$THIRD_PARTY_DIR/libaribcaption/patches/0001-android-explicit-font-path.patch"
    if git -C "$aribcaption" apply --check "$font_patch"; then
        git -C "$aribcaption" apply "$font_patch"
    elif ! git -C "$aribcaption" apply -R --check "$font_patch"; then
        printf 'libaribcaption font patch is neither applicable nor already applied.\n' >&2
        exit 1
    fi
    : > "$aribcaption/.aribplayer-patch-applied"
fi
